-- ============================================================
-- DIAGNOSTIC — Situacao 088 (Concluso para julgamento) — EPROC
--
-- Situacao 088 is NOT mapped from movements in situacoes.json.
-- It is GENERATED by process_special_situacoes() in the script.
--
-- Logic (mirrors script exactly):
--   1. Find rows where situacao IN start_with (all_ints = start ∪ end)
--   2. For each such row, check next row per id_processo (lead by dth_inicio)
--   3. If next situacao is in (start_with ∪ end_with) → dth_fim = next.dth_inicio
--      else dth_fim = NULL
--   4. Filter: keep only rows where dth_fim IS NULL OR dth_fim > dth_inicio
--   5. Force situacao = 88 on all kept rows
--
-- start_with codes come from:
--   eproc2g/json/situacoes_start_end.json → { "situacao": 88, "start_with": [...] }
-- end_with codes come from same entry → "end_with": [...]
--
-- NOTE: all_ints = DISTINCT(start_with ∪ end_with) — used for lead() check.
-- ============================================================

-- ── 1. Verify situacao 088 rows exist in output ────────────────────────────
SELECT situacao, count(*) AS n_rows,
       sum(CASE WHEN dth_fim IS NOT NULL THEN 1 ELSE 0 END) AS n_closed,
       sum(CASE WHEN dth_fim IS NULL     THEN 1 ELSE 0 END) AS n_open
FROM dw_2inst_ouro.tb_tf_situacao_eproc
WHERE situacao = 88
  AND year_month = '2026-01'
GROUP BY situacao;


-- ── 2. Simulate process_special_situacoes() for 088 ───────────────────────
-- start_with and all_ints values from:
--   eproc2g/json/situacoes_start_end.json → situacao 88
--
-- start_with: [159, 81, 160, 90, 18, 9, 82, 24, 26, 65, 62, 27, 28, 29,
--              138, 97, 98, 20, 106, 107, 99, 100, 105, 101, 103, 102,
--              104, 137, 91, 72, 37, 131, 120, 119, 61, 40, 130, 118, 153, 129]
--
-- all_ints = start_with ∪ end_with (all codes that can open or close 088)
-- The end_with list is long — see situacoes_start_end.json for full set.
-- Here we show only the start_with rows before lead() filter.
WITH base AS (
    SELECT
        id_processo,
        dth_inicio,
        situacao,
        LEAD(situacao)   OVER (PARTITION BY id_processo ORDER BY dth_inicio) AS next_situacao,
        LEAD(dth_inicio) OVER (PARTITION BY id_processo ORDER BY dth_inicio) AS next_dth
    FROM dw_2inst_ouro.tb_tf_situacao_eproc
    WHERE YEAR(dth_inicio) = 2026
      AND MONTH(dth_inicio) = 1
),
candidates AS (
    SELECT
        id_processo,
        dth_inicio,
        situacao,
        next_situacao,
        next_dth,
        -- ↓ all_ints: start_with ∪ end_with from situacoes_start_end.json for 088
        CASE
            WHEN next_situacao IN (
                159, 81, 160, 90, 18, 9, 82, 24, 26, 65, 62, 27, 28, 29,
                138, 97, 98, 20, 106, 107, 99, 100, 105, 101, 103, 102,
                104, 137, 91, 72, 37, 131, 120, 119, 61, 40, 130, 118, 153, 129,
                2, 10, 23, 155
            )
            THEN next_dth
            ELSE NULL
        END AS dth_fim_computed
    FROM base
    -- ↓ start_with filter from situacoes_start_end.json for 088
    WHERE situacao IN (
        159, 81, 160, 90, 18, 9, 82, 24, 26, 65, 62, 27, 28, 29,
        138, 97, 98, 20, 106, 107, 99, 100, 105, 101, 103, 102,
        104, 137, 91, 72, 37, 131, 120, 119, 61, 40, 130, 118, 153, 129
    )
)
SELECT
    id_processo,
    dth_inicio,
    situacao          AS trigger_situacao,
    88                AS generated_situacao,
    next_situacao     AS closer_situacao,
    next_dth,
    dth_fim_computed,
    -- script keeps row only when dth_fim NULL or dth_fim > dth_inicio
    CASE
        WHEN dth_fim_computed IS NULL OR dth_fim_computed > dth_inicio THEN 'KEEP'
        ELSE 'DROP'
    END AS row_decision
FROM candidates
ORDER BY id_processo, dth_inicio
LIMIT 50;


-- ── 3. Cross-check: count simulated vs written ────────────────────────────
-- Simulated count should equal n_rows from query 1.
WITH base AS (
    SELECT
        id_processo,
        dth_inicio,
        situacao,
        LEAD(situacao)   OVER (PARTITION BY id_processo ORDER BY dth_inicio) AS next_situacao,
        LEAD(dth_inicio) OVER (PARTITION BY id_processo ORDER BY dth_inicio) AS next_dth
    FROM dw_2inst_ouro.tb_tf_situacao_eproc
    WHERE YEAR(dth_inicio) = 2026
      AND MONTH(dth_inicio) = 1
),
simulated AS (
    SELECT
        id_processo,
        dth_inicio,
        CASE
            WHEN next_situacao IN (
                159, 81, 160, 90, 18, 9, 82, 24, 26, 65, 62, 27, 28, 29,
                138, 97, 98, 20, 106, 107, 99, 100, 105, 101, 103, 102,
                104, 137, 91, 72, 37, 131, 120, 119, 61, 40, 130, 118, 153, 129,
                2, 10, 23, 155
            )
            THEN next_dth
            ELSE NULL
        END AS dth_fim_computed
    FROM base
    WHERE situacao IN (
        159, 81, 160, 90, 18, 9, 82, 24, 26, 65, 62, 27, 28, 29,
        138, 97, 98, 20, 106, 107, 99, 100, 105, 101, 103, 102,
        104, 137, 91, 72, 37, 131, 120, 119, 61, 40, 130, 118, 153, 129
    )
),
kept AS (
    SELECT count(*) AS n_simulated
    FROM simulated
    WHERE dth_fim_computed IS NULL OR dth_fim_computed > dth_inicio
),
written AS (
    SELECT count(*) AS n_written
    FROM dw_2inst_ouro.tb_tf_situacao_eproc
    WHERE situacao = 88
      AND year_month = '2026-01'
)
SELECT k.n_simulated, w.n_written,
       k.n_simulated - w.n_written AS diff
FROM kept k, written w;
